oxy_webhelp_navlinks = {"evaluate_db2_protection_options-d39307e34318":{"topics":[{"title":"Primary snapshot retention for Db2","shortdesc":"<p class=\"shortdesc\">Primary snapshot retention for Db2 databases provides data protection and         recoverability by making it possible to set various retention policies. These policies         include hourly, daily, monthly, and yearly retention of snapshots to meet compliance,         business continuity, and disaster recovery requirements.<\/p>","href":"db2\/primary_snapshot_retention_db2.html","attributes":{"data-id":"primary_snapshot_retention_db2"},"menu":{"hasChildren":false},"tocID":"primary_snapshot_retention_db2-d39307e34329","topics":[]},{"title":"Retention lock for Db2 protection","shortdesc":"<p class=\"shortdesc\">A retention lock on an <span class=\"ph\">RSC<\/span> SLA Domain is a security feature that         prevents premature deletion of Db2 snapshots.<\/p>","href":"db2\/retention_lock_db2_protection.html","attributes":{"data-id":"retention_lock_db2_protection"},"menu":{"hasChildren":false},"tocID":"retention_lock_db2_protection-d39307e34340","topics":[]},{"title":"Multiple archival locations for Db2","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports multiple archival locations for Db2 objects, providing         granular control over data archiving with up to two distinct archiving policies.<\/p>","href":"db2\/multiple_archival_locations_db2.html","attributes":{"data-id":"multiple_archival_locations_db2"},"menu":{"hasChildren":false},"tocID":"multiple_archival_locations_db2-d39307e34354","topics":[]},{"title":"Archiving for Db2 snapshots","shortdesc":"<p class=\"shortdesc\">You can include an archival policy in an SLA Domain to archive Db2 snapshots to an         archival location for long-term retention.<\/p>","href":"db2\/archiving_db2_snapshots.html","attributes":{"data-id":"archiving_db2_snapshots"},"menu":{"hasChildren":false},"tocID":"archiving_db2_snapshots-d39307e34367","topics":[]},{"title":"Db2 snapshots replication","shortdesc":"<p class=\"shortdesc\">You can use the SLA Domain replication policy to replicate Db2 snapshots from one         Rubrik cluster to another for disaster recovery.<\/p>","href":"db2\/db2_snapshots_replication.html","attributes":{"data-id":"db2_snapshots_replication"},"menu":{"hasChildren":false},"tocID":"db2_snapshots_replication-d39307e34378","topics":[]},{"title":"Parallelism and sessions at the database level","shortdesc":"<p class=\"shortdesc\">Parallelism is the ability to simultaneously read and back up different sections         within the database during backup operations. Sessions represent the maximum number of concurrent connections allowed between Db2 and the         Rubrik cluster. With support for parallelism and         sessions at the database level, you can optimize your backup process for improved efficiency         and speed.<\/p>","href":"db2\/parallelism_sessions_database_level.html","attributes":{"data-id":"parallelism_sessions_database_level"},"menu":{"hasChildren":false},"tocID":"parallelism_sessions_database_level-d39307e34389","topics":[]},{"title":"Db2 backup compression","shortdesc":"<p class=\"shortdesc\">Db2 backup compression reduces the storage footprint of Db2 backups by compressing         backup data at the source using Db2 default compression.<\/p>","href":"db2\/db2_compressed_backups.html","attributes":{"data-id":"db2_compressed_backups"},"menu":{"hasChildren":false},"tocID":"db2_compressed_backups-d39307e34400","topics":[]}]}};